import { createHash, createHmac, randomBytes, scrypt, timingSafeEqual, type ScryptOptions } from "node:crypto";
import { z } from "zod";
import { AppError } from "@/lib/errors";
import { clientAddress } from "@/lib/server/rate-limit";

/**
 * Reviewer sessions with named credentials. `REROUTE_REVIEWERS` lists each reviewer as
 * `{ id, displayName, scryptHash, salt }` (generated by `scripts/reviewer-credentials.ts`; no plaintext
 * passcodes anywhere in config). A reviewer signs in with their id (or display name) + personal passcode and
 * gets a 4-hour HttpOnly, SameSite=Strict cookie signed with HMAC-SHA256 (`REROUTE_SESSION_SECRET`). The
 * session's reviewer identity is the configured displayName — never text from the request. Each session
 * carries the reviewer id and a `credVersion` derived from the stored hash, so rotating a reviewer's
 * credentials (or removing them) invalidates their existing sessions. Missing or invalid config ⇒ sign-in is
 * disabled (NOT_CONFIGURED), never open.
 *
 * Used by route handlers and by `src/proxy.ts` (Node runtime), so it stays free of `server-only`; it is never
 * imported by client code.
 */

export const SESSION_COOKIE = "reroute_reviewer";
export const SESSION_TTL_SECONDS = 4 * 60 * 60;
const MIN_SECRET_LENGTH = 32;
/** Tolerated clock skew for `iat` between instances. */
const CLOCK_SKEW_SECONDS = 60;

/** scrypt parameters shared by sign-in and `scripts/reviewer-credentials.ts` (changing them = re-issue all). */
export const SCRYPT_KEY_LENGTH = 32;
export const SCRYPT_SALT_BYTES = 16;
const SCRYPT_OPTIONS: ScryptOptions = { N: 16_384, r: 8, p: 1, maxmem: 64 * 1024 * 1024 };

export const ReviewerNameSchema = z
  .string()
  .trim()
  .min(1, "Display name is empty")
  .max(80)
  .regex(/^[^\p{Cc}]+$/u, "Display name contains control characters");

const ReviewerIdSchema = z
  .string()
  .trim()
  .regex(/^[a-z0-9][a-z0-9._-]{0,39}$/, "Reviewer id must be 1–40 chars of a-z 0-9 . _ - (lowercase)");

const base64urlBytes = (min: number, max: number) =>
  z
    .string()
    .trim()
    .regex(/^[A-Za-z0-9_-]+$/, "Must be base64url")
    .refine((s) => {
      const n = Buffer.from(s, "base64url").length;
      return n >= min && n <= max;
    }, `Must decode to ${min === max ? min : `${min}–${max}`} bytes`);

const ReviewerCredentialSchema = z.object({
  id: ReviewerIdSchema,
  displayName: ReviewerNameSchema,
  scryptHash: base64urlBytes(SCRYPT_KEY_LENGTH, SCRYPT_KEY_LENGTH),
  salt: base64urlBytes(SCRYPT_SALT_BYTES, 64),
});
export type ReviewerCredential = z.infer<typeof ReviewerCredentialSchema>;

type Reviewer = { id: string; displayName: string; hash: Buffer; salt: Buffer; credVersion: string };
type AuthConfig = { secret: string; byId: Map<string, Reviewer>; byLogin: Map<string, Reviewer> };

const normalizeLogin = (login: string) => login.trim().toLowerCase();

/** Fingerprint of a reviewer's stored credential: changes whenever their hash or salt is rotated. */
export function credVersion(c: Pick<ReviewerCredential, "scryptHash" | "salt">): string {
  return createHash("sha256").update(`${c.salt.trim()}:${c.scryptHash.trim()}`).digest("base64url").slice(0, 16);
}

/**
 * `REROUTE_REVIEWERS`: a JSON array of `{ id, displayName, scryptHash, salt }`, or the compact
 * `id:displayName:scryptHash:salt;…` form (display names then may not contain `:` or `;`). Hash and salt are
 * base64url. Throws on any invalid entry or on an id / display name that collides with another reviewer's.
 */
export function parseReviewers(raw: string): ReviewerCredential[] {
  const text = raw.trim();
  let entries: unknown;
  if (text.startsWith("[")) {
    entries = JSON.parse(text);
  } else {
    entries = text
      .split(";")
      .map((e) => e.trim())
      .filter(Boolean)
      .map((e) => {
        const parts = e.split(":");
        if (parts.length !== 4) throw new Error("Each reviewer must be id:displayName:scryptHash:salt");
        const [id, displayName, scryptHash, salt] = parts;
        return { id, displayName, scryptHash, salt };
      });
  }
  const reviewers = z.array(ReviewerCredentialSchema).min(1, "No reviewers configured").parse(entries);
  const logins = new Set<string>();
  for (const r of reviewers) {
    for (const login of new Set([normalizeLogin(r.id), normalizeLogin(r.displayName)])) {
      if (logins.has(login)) throw new Error("Reviewer ids and display names must be unique (case-insensitive)");
      logins.add(login);
    }
  }
  return reviewers;
}

let cached: { raw: string; reviewers: Pick<AuthConfig, "byId" | "byLogin"> | null } | null = null;

function loadReviewers(raw: string): Pick<AuthConfig, "byId" | "byLogin"> | null {
  if (cached?.raw === raw) return cached.reviewers;
  let reviewers: Pick<AuthConfig, "byId" | "byLogin"> | null = null;
  if (raw.trim()) {
    try {
      const byId = new Map<string, Reviewer>();
      const byLogin = new Map<string, Reviewer>();
      for (const c of parseReviewers(raw)) {
        const r: Reviewer = {
          id: c.id,
          displayName: c.displayName,
          hash: Buffer.from(c.scryptHash, "base64url"),
          salt: Buffer.from(c.salt, "base64url"),
          credVersion: credVersion(c),
        };
        byId.set(r.id, r);
        byLogin.set(normalizeLogin(r.id), r);
        byLogin.set(normalizeLogin(r.displayName), r);
      }
      reviewers = { byId, byLogin };
    } catch (err) {
      // Issue paths/messages only — never the configured values.
      const detail = err instanceof z.ZodError ? err.issues.map((i) => `${i.path.join(".")}: ${i.message}`).join("; ") : err instanceof SyntaxError ? "not valid JSON" : String((err as Error).message);
      console.error(`[reroute auth] REROUTE_REVIEWERS is invalid — reviewer sign-in disabled (${detail})`);
    }
  }
  cached = { raw, reviewers };
  return reviewers;
}

/** null = reviewer sign-in disabled (reviewers missing/invalid, or session secret missing/too short). */
export function authConfig(): AuthConfig | null {
  const secret = process.env.REROUTE_SESSION_SECRET ?? "";
  if (secret.length < MIN_SECRET_LENGTH) return null;
  const reviewers = loadReviewers(process.env.REROUTE_REVIEWERS ?? "");
  return reviewers && { secret, ...reviewers };
}

function requireConfig(): AuthConfig {
  const config = authConfig();
  if (!config) {
    throw new AppError(
      "NOT_CONFIGURED",
      `Reviewer sign-in is disabled: set REROUTE_REVIEWERS (scripts/reviewer-credentials.ts) and REROUTE_SESSION_SECRET (≥ ${MIN_SECRET_LENGTH} chars)`,
    );
  }
  return config;
}

/** scrypt-derives the stored hash for `passcode` (also used by `scripts/reviewer-credentials.ts`). */
export function hashPasscode(passcode: string, salt: Buffer): Promise<Buffer> {
  const { promise, resolve, reject } = Promise.withResolvers<Buffer>();
  scrypt(passcode.normalize("NFC"), salt, SCRYPT_KEY_LENGTH, SCRYPT_OPTIONS, (err, key) => (err ? reject(err) : resolve(key)));
  return promise;
}

/** Stand-in credential for unknown reviewers, so they cost the same scrypt + compare as a real one. */
const DUMMY = { salt: randomBytes(SCRYPT_SALT_BYTES), hash: randomBytes(SCRYPT_KEY_LENGTH) };

/** The reviewer whose id/display name is `login` and whose passcode is `passcode`; null otherwise (constant work). */
async function verifyCredentials(config: AuthConfig, login: string, passcode: string): Promise<Reviewer | null> {
  const reviewer = config.byLogin.get(normalizeLogin(login));
  const target = reviewer ?? DUMMY;
  const derived = await hashPasscode(passcode, target.salt);
  const matches = timingSafeEqual(derived, target.hash);
  return matches && reviewer ? reviewer : null;
}

/** What the signed cookie carries. Identity is looked up in config on every request. */
const TokenSchema = z.object({
  sub: ReviewerIdSchema,
  ver: z.string().min(1).max(64),
  iat: z.number().int(),
  exp: z.number().int(),
});
export type SessionToken = z.infer<typeof TokenSchema>;

/** A verified session: `reviewer` is the configured display name of reviewer `reviewerId`. */
export type ReviewerSession = { reviewerId: string; reviewer: string; iat: number; exp: number };

function mac(secret: string, data: string): Buffer {
  return createHmac("sha256", secret).update(data).digest();
}

/** `<base64url(json)>.<base64url(hmac)>` */
export function signSession(token: SessionToken, secret: string): string {
  const body = Buffer.from(JSON.stringify(token)).toString("base64url");
  return `${body}.${mac(secret, body).toString("base64url")}`;
}

/** The token if the signature, shape and lifetime all check out; otherwise null. */
export function verifySession(token: string, secret: string, nowSeconds: number): SessionToken | null {
  const parts = token.split(".");
  if (parts.length !== 2 || !parts[0] || !parts[1]) return null;
  const [body, signature] = parts;
  const expected = mac(secret, body);
  const given = Buffer.from(signature, "base64url");
  if (given.length !== expected.length || !timingSafeEqual(given, expected)) return null;
  let json: unknown;
  try {
    json = JSON.parse(Buffer.from(body, "base64url").toString("utf8"));
  } catch {
    return null;
  }
  const parsed = TokenSchema.safeParse(json);
  if (!parsed.success) return null;
  const { iat, exp } = parsed.data;
  if (exp <= nowSeconds || iat > nowSeconds + CLOCK_SKEW_SECONDS || exp - iat > SESSION_TTL_SECONDS) return null;
  return parsed.data;
}

function readCookie(req: Request, name: string): string | undefined {
  for (const part of (req.headers.get("cookie") ?? "").split(";")) {
    const eq = part.indexOf("=");
    if (eq !== -1 && part.slice(0, eq).trim() === name) return part.slice(eq + 1).trim();
  }
  return undefined;
}

/**
 * The signed-in reviewer, or null: also null when sign-in is disabled, when the reviewer was removed from
 * config, or when their credentials were rotated after the session was issued.
 */
export async function getSession(req: Request, now: Date = new Date()): Promise<ReviewerSession | null> {
  const config = authConfig();
  const cookieValue = readCookie(req, SESSION_COOKIE);
  if (!config || !cookieValue) return null;
  const token = verifySession(cookieValue, config.secret, Math.floor(now.getTime() / 1000));
  if (!token) return null;
  const reviewer = config.byId.get(token.sub);
  if (!reviewer || reviewer.credVersion !== token.ver) return null;
  return { reviewerId: reviewer.id, reviewer: reviewer.displayName, iat: token.iat, exp: token.exp };
}

/** Reviewer identity always comes from the session + config, never from a request body. */
export async function requireReviewer(req: Request): Promise<{ reviewer: string; reviewerId: string }> {
  requireConfig();
  const session = await getSession(req);
  if (!session) throw new AppError("FORBIDDEN", "Sign in as a reviewer to do this");
  return { reviewer: session.reviewer, reviewerId: session.reviewerId };
}

export type SessionCookie = {
  name: string;
  value: string;
  options: { httpOnly: true; secure: boolean; sameSite: "strict"; path: "/"; maxAge: number };
};

function cookie(value: string, maxAge: number): SessionCookie {
  return {
    name: SESSION_COOKIE,
    value,
    options: { httpOnly: true, secure: process.env.NODE_ENV === "production", sameSite: "strict", path: "/", maxAge },
  };
}

/**
 * Checks the reviewer's personal passcode (FORBIDDEN on an unknown reviewer or wrong passcode — the same
 * answer for both) and issues a signed 4-hour session cookie for the configured identity.
 */
export async function signIn(
  login: string,
  passcode: string,
  now: Date = new Date(),
): Promise<{ session: ReviewerSession; cookie: SessionCookie }> {
  const config = requireConfig();
  const reviewer = await verifyCredentials(config, login, passcode);
  if (!reviewer) throw new AppError("FORBIDDEN", "Wrong reviewer or passcode");
  const iat = Math.floor(now.getTime() / 1000);
  const token: SessionToken = { sub: reviewer.id, ver: reviewer.credVersion, iat, exp: iat + SESSION_TTL_SECONDS };
  return {
    session: { reviewerId: reviewer.id, reviewer: reviewer.displayName, iat, exp: token.exp },
    cookie: cookie(signSession(token, config.secret), SESSION_TTL_SECONDS),
  };
}

// ---------- Sign-in lockout ----------
//
// Defence in depth only: per server instance and in memory (see lib/server/rate-limit.ts, which also caps
// POST /api/auth/session at 5/min per address in the proxy). On Vercel the real control is a Firewall rule.

export const SIGN_IN_FAILURE_DELAY_MS = 750;
export const SIGN_IN_MAX_FAILURES = 10;
export const SIGN_IN_WINDOW_MS = 15 * 60 * 1000;
/** Bound on tracked client addresses, so a spray of addresses cannot grow memory without limit. */
const SIGN_IN_MAX_TRACKED = 10_000;

/** Failure timestamps per client address within the current window. */
const signInFailures = new Map<string, number[]>();

function recentFailures(address: string, now: number): number[] {
  const recent = (signInFailures.get(address) ?? []).filter((t) => now - t < SIGN_IN_WINDOW_MS);
  if (recent.length) signInFailures.set(address, recent);
  else signInFailures.delete(address);
  return recent;
}

function recordSignInFailure(address: string, now: number): void {
  if (!signInFailures.has(address) && signInFailures.size >= SIGN_IN_MAX_TRACKED) {
    for (const key of signInFailures.keys()) recentFailures(key, now);
    // Still full: forget the oldest-tracked address (Map iterates in insertion order).
    if (signInFailures.size >= SIGN_IN_MAX_TRACKED) signInFailures.delete(signInFailures.keys().next().value!);
  }
  signInFailures.set(address, [...recentFailures(address, now), now]);
}

export function resetSignInThrottleForTests(): void {
  signInFailures.clear();
}

/**
 * `signIn` behind the lockout: while an address has SIGN_IN_MAX_FAILURES failures in the window every
 * attempt (even a correct passcode) gets RATE_LIMITED; a failed attempt is answered no sooner than
 * SIGN_IN_FAILURE_DELAY_MS after it arrived.
 */
export async function attemptSignIn(
  req: Request,
  login: string,
  passcode: string,
): Promise<{ session: ReviewerSession; cookie: SessionCookie }> {
  const address = clientAddress(req);
  const recent = recentFailures(address, Date.now());
  if (recent.length >= SIGN_IN_MAX_FAILURES) {
    const retryAfter = Math.max(1, Math.ceil((recent[0] + SIGN_IN_WINDOW_MS - Date.now()) / 1000));
    throw new AppError("RATE_LIMITED", "Too many failed sign-in attempts; try again later", {
      headers: { "Retry-After": String(retryAfter) },
    });
  }
  const { promise: floor, resolve } = Promise.withResolvers<void>();
  const timer = setTimeout(resolve, SIGN_IN_FAILURE_DELAY_MS);
  try {
    const result = await signIn(login, passcode);
    clearTimeout(timer);
    return result;
  } catch (err) {
    if (err instanceof AppError && err.code === "FORBIDDEN") {
      recordSignInFailure(address, Date.now());
      await floor;
    } else {
      clearTimeout(timer);
    }
    throw err;
  }
}

export function signOutCookie(): SessionCookie {
  return cookie("", 0);
}

/**
 * CSRF guard for mutating requests: the browser must say the request is same-origin (Sec-Fetch-Site) and/or
 * send an Origin whose host is this server's host. Requests carrying neither are rejected.
 */
export function isSameOrigin(req: Request): boolean {
  const site = req.headers.get("sec-fetch-site");
  if (site && site !== "same-origin") return false;
  const origin = req.headers.get("origin");
  if (!origin) return site === "same-origin";
  let originHost: string;
  try {
    originHost = new URL(origin).host;
  } catch {
    return false; // includes the opaque "null" origin
  }
  const host = req.headers.get("x-forwarded-host") ?? req.headers.get("host");
  return !!host && originHost === host;
}
